388	    pub fn get_mut(&mut self, attr: HtmlAttr) -> Option<&mut EcoString> {
389	        self.0
390	            .make_mut()
391	            .iter_mut()
392	            .find(|&&mut (k, _)| k == attr)
393	            .map(|(_, v)| v)
394	    }
395	}
