412	cast! {
413	    HtmlAttrs,
414	    self => self.0
415	        .into_iter()
416	        .map(|(key, value)| (key.resolve().as_str().into(), value.into_value()))
417	        .collect::<Dict>()
418	        .into_value(),
419	    values: Dict => Self(values
420	        .into_iter()
421	        .map(|(k, v)| {
422	            let attr = HtmlAttr::intern(&k)?;
423	            let value = v.cast::<EcoString>()?;
424	            Ok((attr, value))
425	        })
426	        .collect::<HintedStrResult<_>>()?),
427	}
